Sure! I'll create a toggle function in FlagToggle.js. Here's the initial implementation:

```javascript
// src/flags/FlagToggle.js
const flags = {};

function toggleFlag(flagName) {
    if (flags[flagName] !== undefined) {
        flags[flagName] = !flags[flagName];
    } else {
        throw new Error('Flag does not exist');
    }
}

module.exports = { toggleFlag };
```

Next, I'll update the FlagService.js to utilize this toggle function:

```javascript
// src/flags/FlagService.js
const { toggleFlag } = require('./FlagToggle');

function enableFlag(flagName) {
    toggleFlag(flagName);
    return `${flagName} has been toggled.`;
}

module.exports = { enableFlag };
```

Let's write a test for it in FlagToggle.test.js.
```javascript
// tests/FlagToggle.test.js
const { toggleFlag } = require('../src/flags/FlagToggle');

test('toggleFlag changes flag state', () => {
    const flagName = 'testFlag';
    flags[flagName] = false;
    toggleFlag(flagName);
    expect(flags[flagName]).toBe(true);
    toggleFlag(flagName);
    expect(flags[flagName]).toBe(false);
});
```

